#!/bin/sh
set -eu
cd "$(dirname "$0")"
OUT=build_all.sql
cat > "$OUT" <<'EOF'
-- Generated by make_build_all.sh. Rebuilds the disposable course database.
DROP DATABASE IF EXISTS volunteer_db;
CREATE DATABASE volunteer_db CHARACTER SET utf8mb4;
USE volunteer_db;
SET SESSION time_zone = '+00:00';
EOF

for dir in 00_setup 01_tables 02_routines 03_triggers 04_seed 07_security; do
  for f in volunteer_DB/"$dir"/*.sql; do
    [ -e "$f" ] || continue
    cat "$f" >> "$OUT"
    printf '\n\n' >> "$OUT"
  done
done

printf 'Wrote %s (reports and tests run separately)\n' "$OUT"
